'use strict';
(()=>{
 const $=id=>document.getElementById(id),id=new URLSearchParams(location.search).get('id'),history=[],form=$('chat-form'),input=$('message');let busy=false;
 try{document.documentElement.dataset.theme=localStorage.getItem('jh-theme')||'light';}catch{}
 $('theme').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';};
 function bubble(role,text){const p=document.createElement('div');p.className='bubble '+role;p.textContent=text;$('messages').append(p);$('messages').scrollTop=$('messages').scrollHeight;}
 async function api(action,body){const r=await fetch('/api/secretj-botfolio?action='+action,{credentials:body?'same-origin':'omit',cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});let d;try{d=await r.json();}catch{throw Error('Service unavailable.');}if(!r.ok||!d.ok)throw Error(d.error||'Request failed.');return d;}
 async function send(message){if(busy||!message.trim())return;busy=true;form.querySelector('button').disabled=true;input.disabled=true;const prior=history.slice(-6);bubble('user',message);$('chat-status').textContent='Thinking…';input.value='';try{const r=await api('chat',{id,message,history:prior});bubble('assistant',r.answer);history.push({role:'user',content:message},{role:'assistant',content:r.answer});if(history.length>6)history.splice(0,history.length-6);$('chat-status').textContent='';}catch(e){$('chat-status').textContent=e.message;input.value=message;}finally{busy=false;form.querySelector('button').disabled=false;input.disabled=false;input.focus();}}
 form.onsubmit=e=>{e.preventDefault();send(input.value.trim());};$('suggestions').onclick=e=>{if(e.target.tagName==='BUTTON')send(e.target.textContent);};
 (async()=>{try{if(!id)throw Error('Missing portfolio link.');const r=await api('public&id='+encodeURIComponent(id));$('name').textContent=r.bot.name;$('headline').textContent=r.bot.headline;document.title=r.bot.name+' · Botfolio';bubble('assistant','Hi! I am the AI portfolio assistant for '+r.bot.name+'. Ask me about the published skills, experience or projects.');form.hidden=false;$('suggestions').hidden=false;}catch(e){$('name').textContent='Portfolio unavailable';$('chat-status').textContent=e.message;}})();
})();
